REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (0,'元宝',0,0,0,0,0,0,1,0,0,'元宝用于购买商城中的道具。不能用于交易。','元宝是在商城中购买道具时使用。',1,0,0,'',0,0,0),
     (1,'传音符',1,0,0,0,0,0,-1,0,0,'在世界频道发言需要消耗1个传音符，群发信件需要消耗2个传音符。','传音符是在世界频道聊天的时候使用。',0,0,8,'',0,0,0),
     (2,'神农锄',1,0,5,10,0,1,8,2,0,'粮食产量增加25%，至少增加产量500/小时。持续24小时。连续使用时间延长。额外获得粮食500。','',1,0,8,'',0,1,0),
     (3,'鲁班斧',1,0,5,10,0,1,8,2,0,'木材产量增加25%，至少增加产量500/小时。持续24小时。连续使用时间延长。额外获得木材500。','',1,0,8,'',0,1,0),
     (4,'开山锤',1,0,5,10,0,1,8,2,0,'石料产量增加25%，至少增加产量500/小时。持续24小时。连续使用时间延长。额外获得石料500。','',1,0,8,'',0,1,0),
     (5,'玄铁炉',1,0,5,10,0,1,8,2,0,'铁锭产量增加25%，至少增加产量500/小时。持续24小时。连续使用时间延长。额外获得铁锭500。','',1,0,8,'',0,1,0),
     (6,'陷阵战鼓',1,0,5,10,0,1,10,0,0,'冲锋陷阵时擂响的战鼓，士兵闻之即士气大振，必勇猛向前，攻无不克。军队攻击增加10%，持续24小时。连续使用时间延长。','',1,0,6,'',0,1,0),
     (7,'八卦阵图',1,0,5,10,0,1,10,0,0,'以周易八卦推演而成的作战阵法，防守时不动如山，可当十万精兵。军队防御增加10%，持续24小时。连续使用时间延长。','',1,0,6,'',0,1,0),
     (8,'墨家残卷',1,15,20,10,0,10,5,1,0,'记载了墨家工艺的残破书卷。使用后缩短1项研究任务的时间15分钟。','墨家残卷是在研究科技的时候，点击“加速”来使用。',0,0,8,'',0,0,0),
     (9,'墨家图纸',1,0,1,10,15,1,25,1,0,'记载了墨家工艺的完整图纸。使用后缩短1项研究任务的时间3小时。','墨家图纸是在研究科技的时候，点击“加速”来使用。',0,0,7,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (10,'墨家宝典',1,0,0,1,5,0,150,1,0,'收录了墨家工艺精华的珍贵典籍。使用后缩短1项研究任务的时间35%。','墨家宝典是在研究科技的时候，点击“加速”来使用。',0,0,3,'',0,0,0),
     (11,'木牛流马',1,5,15,10,0,5,5,1,0,'以精巧的机关术制造出来的运输工具，能够快捷地运输大批物资。使用后缩短1笔交易的时间为1/10。','木牛流马是在市场里，点击行进中的商队的“加速”来使用。',0,0,8,'',0,0,0),
     (12,'免战牌',1,0,0,5,15,0,20,0,0,'使用后进入“免战”状态，避免其他玩家对城池的攻击，自己也无法向他人出征。持续12小时，连续使用时间延长，免战结束3小时后才可以再次使用。对出征途中的敌人无效。野地和名城不受免战保护。','免战牌是在玩家信息中更改状态时使用。',1,0,6,'',0,0,0),
     (13,'锦囊',1,10,25,20,10,5,5,0,0,'使用计谋需要消耗锦囊。','锦囊是在使用计谋时使用。',0,0,8,'',0,0,0),
     (14,'盟主密诏',1,0,0,0,0,0,100,0,0,'盟主失踪后，群龙无首，战乱纷纷。使用后，可以成为盟主。只有副盟主才可以使用','',1,0,0,'',0,0,0),
     (15,'盟主令',1,0,0,0,1,0,500,0,0,'使用后将本联盟的成员人数上限直接提升为150。','',1,0,1,'',0,0,0),
     (16,'青铜礼匣',1,5,0,0,0,5,10,3,0,'锁住的青铜礼匣，用青铜钥匙打开后可以获得宝物。','',1,0,5,'',0,1,0),
     (17,'白银礼匣',1,2,0,0,0,2,60,3,0,'锁住的白银礼匣，用白银钥匙打开后可以获得宝物。','',1,0,2,'',0,1,0),
     (18,'黄金礼匣',1,1,0,0,0,1,160,3,0,'锁住的黄金礼匣，用黄金钥匙打开后可以获得宝物。','',1,0,1,'',0,1,0),
     (19,'青铜钥匙',1,2,2,3,0,2,5,3,0,'精巧的青铜钥匙，用于开启青铜礼匣。','',1,0,7,'',0,1,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (20,'白银钥匙',1,0,1,2,2,0,30,3,0,'精巧的白银钥匙，用于开启白银礼匣。','',1,0,6,'',0,1,0),
     (21,'黄金钥匙',1,0,0,1,1,0,80,3,0,'精巧的黄金钥匙，用于开启黄金礼匣。','',1,0,5,'',0,1,0),
     (22,'洗髓丹',1,5,10,15,10,5,20,0,0,'将领的属性回到初始状态，可以重新配置属性点。将领等级每高10级需要多消耗1颗洗髓丹。','洗髓丹是在将领界面中给将领洗点时使用。',0,0,6,'',0,0,0),
     (23,'招贤榜',1,10,20,20,20,10,5,0,0,'使用后，立即将本城池的客栈刷新，出现新的将领。','招贤榜在客栈的“招贤纳士”处使用。',0,0,8,'',0,0,0),
     (24,'迁城令',1,0,0,5,15,0,30,0,0,'将城池迁徙到其他地方。需要选择一个州，然后在该州内随机落户。使用时不能有军队在外，城内也不能有盟友的驻军。名城不能迁徙。','',1,0,8,'',0,0,0),
     (25,'青囊书',1,0,0,5,15,0,30,0,0,'增强军队的战场救治能力，让战斗中损失的军队有30%成为额外的伤兵，进入伤兵营等待治疗。效果持续24小时，连续使用时间延长。','',1,0,2,'',0,1,0),
     (26,'虎符',1,0,0,5,20,0,80,0,0,'虎符，赏赐给将领，该将领的统率提高50%。效果持续24小时。连续使用时间延长。','虎符是在将领界面中赏赐将领时使用。',0,0,6,'',0,0,0),
     (27,'文曲星符',1,0,2,5,20,0,40,0,0,'赏赐给将领，该将领内政增加25%。持续24小时。连续使用时间延长。','文曲星符是在将领界面中赏赐将领时使用。',0,0,6,'',0,0,0),
     (28,'武曲星符',1,0,2,5,20,0,40,0,0,'赏赐给将领，该将领勇武增加25%。持续24小时。连续使用时间延长。','武曲星符是在将领界面中赏赐将领时使用。',0,0,6,'',0,0,0),
     (29,'智多星符',1,0,2,5,20,0,40,0,0,'赏赐给将领，该将领智谋增加25%。持续24小时。连续使用时间延长。','智多星符是在将领界面中赏赐将领时使用。',0,0,6,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (30,'珍珠',1,0,18,8,10,8,20,4,0,'珍珠是一种在贝、蚌的体内自然形成的宝石，自古以来一直被人们视做奇珍。赏赐将领，可提高忠诚5。可用于进贡朝廷、招降将领。','珍珠是在赏赐、招降将领时使用。',0,0,8,'',0,0,0),
     (31,'珊瑚',1,0,15,8,10,8,24,4,0,'珊瑚是来自海中多年沉积而成的特产，它造型奇特、玲珑透剔，极具观赏价值。赏赐将领，可提高忠诚10。可用于进贡朝廷、招降将领。','珊瑚是在赏赐、招降将领时使用。',0,0,8,'',0,0,0),
     (32,'琉璃',1,0,12,8,10,5,28,4,0,'琉璃色彩绚丽、变幻瑰美。由彩色水晶烧制而成，其工艺繁复，十分难得。赏赐将领，可提高忠诚15。可用于进贡朝廷、招降将领。','琉璃是在赏赐、招降将领时使用。',0,0,8,'',0,0,0),
     (33,'琥珀',1,0,10,8,10,5,32,4,0,'琥珀是树脂历经千万年固化形成的珍宝，温润如玉，璀璨胜金，晶莹似钻，能发出淡雅的芳香。赏赐将领，可提高忠诚20。可用于进贡朝廷、招降将领。','琥珀是在赏赐、招降将领时使用。',0,0,8,'',0,0,0),
     (34,'玛瑙',1,0,5,8,10,3,40,4,0,'玛瑙是呈带状的玉髓，色彩斑斓，美伦美幻，赏心悦目，令人爱不释手。赏赐将领，可提高忠诚25。可用于进贡朝廷、招降将领。','玛瑙是在赏赐、招降将领时使用。',0,0,8,'',0,0,0),
     (35,'水晶',1,0,5,5,6,3,48,4,0,'水晶是一种无色透明、洁净明亮的宝石，凝聚了千亿万年天地灵气，具有解暑消炎、轻身延年的神奇功效。赏赐将领，可提高忠诚30。可用于进贡朝廷、招降将领。','水晶是在赏赐、招降将领时使用。',0,0,8,'',0,0,0),
     (36,'翡翠',1,0,5,5,6,3,60,4,0,'翡翠是翠绿色的宝石，透明晶莹、光泽鲜丽、硬而不脆，被誉为“玉中之王”。赏赐将领，可提高忠诚40。可用于进贡朝廷、招降将领。','翡翠是在赏赐、招降将领时使用。',0,0,8,'',0,0,0),
     (37,'玉石',1,0,0,5,6,2,80,4,0,'玉石细腻、温润、含蓄幽雅，有避邪的作用，更可雕琢为蕴含丰富文化内涵的精美造型，成为光荣和幸福的化身，刚毅和仁慈的象征。赏赐将领，可提高忠诚50。可用于进贡朝廷、招降将领。','玉石是在赏赐、招降将领时使用。',0,0,8,'',0,0,0),
     (38,'夜明珠',1,0,0,5,6,1,100,4,0,'夜明珠是在黑暗中能自行发光的珠宝，系相当稀有的宝物，被当作镇国宝器。古称“随珠”、“悬珠”、“垂棘”、“明月珠”等。赏赐将领，可提高忠诚60。可用于进贡朝廷、招降将领。','夜明珠是在赏赐、招降将领时使用。',0,0,8,'',0,0,0),
     (39,'旌旗',1,0,10,15,6,0,6,0,0,'更改旗号需要消耗1个旌旗，旗号将显示在地图的城池上方。','旌旗是在玩家信息的“更改旗号”处使用。',1,0,8,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (40,'建筑图纸',1,5,5,10,15,5,50,0,0,'升级建筑到10级以上的时候，需要使用建筑图纸。','建筑图纸是在升级建筑到10级以上时自动消耗。',0,0,3,'',0,0,0),
     (41,'珠宝匣',1,0,0,0,0,0,80,3,0,'装有珍宝的匣子，外表朴实无华，打开后有可能获得2至4个珍珠、珊瑚、琉璃。','',1,0,3,'',0,1,0),
     (42,'精致珠宝匣',1,0,0,0,0,0,140,3,0,'富豪保存传家珍宝的匣子，外表精致华丽，打开后有可能获得2至4个琥珀、玛瑙、水晶。','',1,0,2,'',0,1,0),
     (43,'稀世珠宝匣',1,0,0,0,0,0,240,3,0,'皇室收藏稀世珍宝的匣子，外表精美绝伦，打开后有可能获得2至4个翡翠、玉石、夜明珠。','',1,0,1,'',0,1,0),
     (44,'高级神农锄',1,0,0,5,20,0,50,2,0,'粮食产量增加25%，至少增加产量500/小时。持续7天。连续使用时间延长。额外获得粮食5000。','',1,0,5,'',0,1,0),
     (45,'高级鲁班斧',1,0,0,5,20,0,50,2,0,'木材产量增加25%，至少增加产量500/小时。持续7天。连续使用时间延长。额外获得木材5000。','',1,0,5,'',0,1,0),
     (46,'高级开山锤',1,0,0,5,20,0,50,2,0,'石料产量增加25%，至少增加产量500/小时。持续7天。连续使用时间延长。额外获得石料5000。','',1,0,5,'',0,1,0),
     (47,'高级玄铁炉',1,0,0,5,20,0,50,2,0,'铁锭产量增加25%，至少增加产量500/小时。持续7天。连续使用时间延长。额外获得铁锭5000。','',1,0,5,'',0,1,0),
     (48,'高级陷阵战鼓',1,0,0,5,15,0,60,0,0,'冲锋陷阵时擂响的战鼓，士兵闻之即士气大振，必勇猛向前，攻无不克。军队攻击增加10%，持续7天。连续使用时间延长。','',1,0,5,'',0,1,0),
     (49,'高级八卦阵图',1,0,0,5,15,0,60,0,0,'以周易八卦推演而成的作战阵法，防守时不动如山，可当十万精兵。军队防御增加10%，持续7天。连续使用时间延长。','',1,0,5,'',0,1,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (50,'古朴木匣',1,0,0,0,0,0,100,3,0,'埋藏在地底深处的木匣，历经岁月的沉积，外观古朴厚重，弥散出年代久远的沧桑气息。打开后可随机获得1个宝物道具。在长时间的采集之后有可能获得。','',1,0,7,'',0,1,0),
     (51,'清仓令',1,0,0,0,0,0,70,0,0,'令人时常整理仓库，自动清除超过资源容量上限的过剩资源，可避免因资源堆积过多而引起的灾祸。效果持续7天，连续使用时间延长。','',1,0,0,'',0,0,0),
     (52,'墨家秘笈',1,0,0,2,25,0,100,1,0,'墨家秘密收藏的经典，使用密文书写，外人难以解读。使用后随机缩短1项研究任务的时间12~36小时。','墨家秘笈是在研究科技的时候，点击“加速”来使用。',0,0,2,'',0,0,0),
     (53,'墨家弟子',1,0,0,0,0,0,10000,1,0,'聘请墨家弟子前来相助，立即完成1项建筑或研究任务。根据剩余时间消耗元宝。','',1,0,0,'',0,0,0),
     (54,'税吏鞭',1,0,50,10,0,0,45,2,0,'黄金征税收入增加25%，持续24小时。连续使用时间延长。额外获得黄金500。','',1,0,7,'',0,1,0),
     (55,'高级税吏鞭',1,0,0,5,15,0,280,2,0,'黄金征税收入增加25%，持续7天。连续使用时间延长。额外获得黄金5000。','',1,0,5,'',0,1,0),
     (56,'徭役令',1,0,2,5,20,0,50,0,0,'向百姓征发徭役，驱使大量劳力用于城池建设。使用后可增加3个建造队列，使城池可以同时建造5个建筑。效果持续3天，连续使用时间延长。','',1,0,3,'',0,1,0),
     (57,'典民令',1,0,2,10,10,0,50,0,0,'吸纳大批失去土地的流民作为城池居民，增加人口数量为城池人口上限的20%，最少增加100人。如果城池人口已经超过上限，则不能使用。','',1,0,2,'',0,1,0),
     (58,'安民告示',1,0,0,5,20,0,100,0,0,'安定人心的布告，在全城张贴，可迅速安定人心，让局势恢复平静。对城池使用，立刻让该城池的民心变成100，民怨变成0。使用过的城池在3天内不能再次使用。','',1,0,2,'',0,0,0),
     (59,'军旗',1,2,2,5,10,2,30,0,0,'象征军队建制的旗帜，用于指挥调度大军出征。出征时在校场中使用军旗，可增加出征军队人数上限25%。','军旗是在军队出征的时候在校场使用。',0,0,8,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (60,'考工记简章',1,1,10,15,0,5,50,2,0,'先秦时期手工艺专著的简单版本，粗略记载了各种手工业技术、工艺资料、生产管理和营建制度。适用于等级1到5级的建筑，可让城池内5级以下建筑的建造消耗资源成本降低30%。效果持续24小时，连续使用时间延长。','',1,0,7,'',0,1,0),
     (61,'考工记精编',1,0,0,20,15,0,80,2,0,'先秦时期手工艺专著的精选篇章，择其精华收录了各种手工业技术、工艺资料、生产管理和营建制度。适用于等级1到8级的建筑，可让城池内8级以下建筑的建造消耗资源成本降低30%。效果持续24小时，连续使用时间延长。','',1,0,4,'',0,1,0),
     (62,'考工记秘录',1,0,0,5,20,0,200,2,0,'先秦时期手工艺专著的秘藏部分，收录了秘不外传的各种手工业技术、工艺资料、生产管理和营建制度。适用于等级1到20级的建筑，可让城池内20级以下建筑的建造消耗资源成本降低30%。效果持续24小时，连续使用时间延长。','',1,0,2,'',0,1,0),
     (63,'韩信三篇下部',1,2,5,10,20,2,30,1,0,'韩信点兵，多多益善。韩信兵法中记载了韩信练兵的心得，依照此法练兵，可迅速练出精悍士卒。因吕氏乱政，兵法大部分遗失，仅流传下三篇，此为下部。使用后可缩短当前队列和当前城池其他军营的第一个可加速训练队列剩余时间的30%，至少缩短1小时。每个训练队列只能使用一次','韩信三篇下篇是在军营中对训练队列加速的时候使用。',0,0,6,'',0,0,0),
     (64,'备城门',1,1,5,10,20,1,35,1,0,'墨子的重要军事篇章，记载了墨家对城池攻守器械和城防体系的研究成果。使用后可缩短一个城防建造队列的剩余时间30%。至少缩短30分钟，每个训练队列只能使用一次。','备城门是在城墙中对城防建造队列加速的时候使用。',0,0,6,'',0,0,0),
     (65,'墨家散页',1,1,3,15,10,1,10,1,0,'记载了墨家工艺的零散书页。使用后缩短1项研究任务的时间1小时。','墨家散页是在研究科技的时候，点击“加速”来使用。',0,0,7,'',0,0,0),
     (66,'墨家古籍',1,0,0,5,20,0,65,1,0,'记载了墨家工艺秘诀的古老书籍。使用后缩短1项研究任务的时间10小时。','墨家古籍是在研究科技的时候，点击“加速”来使用。',0,0,5,'',0,0,0),
     (67,'鲁班残页',1,15,20,10,0,10,5,1,0,'记录了鲁班建筑经验的破损书页。使用后缩短1项建造任务的时间15分钟。','鲁班残页是在建造、升级建筑的时候，点击“加速”来使用。',0,0,8,'',0,0,0),
     (68,'鲁班便笺',1,1,3,15,10,1,10,1,0,'记录了鲁班建筑心得的简短纸片。使用后缩短1项建造任务的时间1小时。','鲁班便笺是在建造、升级建筑的时候，点击“加速”来使用。',0,0,7,'',0,0,0),
     (69,'鲁班草图',1,0,1,10,15,1,20,1,0,'记录了鲁班建筑设计的图样，线条有些潦草。使用后缩短1项建造任务的时间2小时30分钟。','鲁班草图是在建造、升级建筑的时候，点击“加速”来使用。',0,0,6,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (70,'鲁班书册',1,0,0,5,20,0,50,1,0,'记录了鲁班建筑工艺诀窍的陈旧书册，便于携带翻阅。使用后缩短1项建造任务的时间8小时。','鲁班书册是在建造、升级建筑的时候，点击“加速”来使用。',0,0,4,'',0,0,0),
     (71,'鲁班秘录',1,0,0,2,25,0,80,1,0,'鲁班祖师爷所传，记录了各种工匠秘诀的经典，其中很多术语晦涩难懂。使用后随机缩短1项建造任务的时间10~30小时。','鲁班秘录是在建造、升级建筑的时候，点击“加速”来使用。',0,0,3,'',0,0,0),
     (72,'鲁班全集',1,0,0,1,5,0,120,1,0,'收集了鲁班毕生全部心血的宝贵文献。使用后缩短1项建造任务的时间30%。','鲁班全集是在建造、升级建筑的时候，点击“加速”来使用。',0,0,2,'',0,0,0),
     (73,'鲁班传人',1,0,0,0,0,0,10000,1,0,'聘请鲁班传人前来相助，立即完成1项建筑任务。根据剩余时间消耗元宝。','',1,0,0,'',0,0,0),
     (74,'止血散',1,2,5,10,0,2,10,1,0,'活血散瘀，定痛消肿的良药。对将领使用，立即恢复将领体力10%。','止血散是在将领界面中给将领加体力时使用。',0,0,8,'',0,0,0),
     (75,'金疮药',1,0,2,15,5,0,30,1,0,'敷上立即止痛止血，治疗刀斧损伤颇有奇效。对将领使用，立即恢复将领体力30%。','金疮药是在将领界面中给将领加体力时使用。',0,0,8,'',0,0,0),
     (76,'大还丹',1,0,1,10,15,0,60,1,0,'独家秘方，疗伤奇药，无论内伤外伤，均可迅速治愈。对将领使用，立即恢复将领体力60%。','大还丹是在将领界面中给将领加体力时使用。',0,0,6,'',0,0,0),
     (77,'九转还魂丹',1,0,0,2,10,0,80,1,0,'极其珍贵的医疗圣药，可以活死人，肉白骨，有起死回生的神奇疗效。对将领使用，立即恢复将领体力100%。','九转还魂丹是在将领界面中给将领加体力时使用。',0,0,4,'',0,0,0),
     (78,'清心丸',1,2,5,10,0,2,10,1,0,'服后如清泉灌顶，可清心解烦，消除疲乏。对将领使用，立即恢复将领精力10%。','清心丸是在将领界面中给将领加精力时使用。',0,0,8,'',0,0,0),
     (79,'醒神丹',1,0,2,15,5,0,30,1,0,'提神醒脑，解除头痛昏厥，服后令人神清气爽，精神百倍。对将领使用，立即恢复将领精力30%。','醒神丹是在将领界面中给将领加精力时使用。',0,0,8,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (80,'天元丹',1,0,1,10,15,0,60,1,0,'以灵药秘制而成，于静虚中养清灵之气，至精气神合一，明心见性。对将领使用，立即恢复将领精力60%。','天元丹是在将领界面中给将领加精力时使用。',0,0,6,'',0,0,0),
     (81,'九花玉露丸',1,0,0,2,10,0,100,1,0,'以雪莲等珍异药材调制而成的灵丹妙药，清香袭人，服后补神健体，延年益寿。对将领使用，立即恢复将领精力100%。','九花玉露丸是在将领界面中给将领加精力时使用。',0,0,4,'',0,0,0),
     (82,'高级迁城令',1,0,2,10,15,0,90,0,0,'将城池迁徙到指定位置的平地上。迁城后12小时内只能对自己的城池运输，不能进行其他出征活动。需要选择无主的平地，输入该平地的坐标。使用时不能有军队在外，城内也不能有盟友的驻军。名城不能迁徙。','',1,0,2,'',0,0,0),
     (83,'火药筒',1,1,10,10,5,1,20,1,0,'塞满火药的竹筒，点燃可炸毁大片建筑。拆除建筑时使用火药筒，可以立即将该建筑完全拆除，使其成为空地。使用火药筒拆除建筑，将无法回收资源。不能对官府使用。','火药筒是在彻底拆除建筑的时候使用。',0,0,4,'',0,0,0),
     (84,'名帖',1,0,0,0,1,0,200,0,0,'君主改名需要消耗1个名帖。','名帖是在玩家信息中更改君主名称时使用。',1,0,1,'',0,0,0),
     (85,'金条',1,0,0,0,0,0,100,3,0,'富贵人家将黄金熔炼成金条，以便保存。熔炼后可获得黄金10万。','',1,0,6,'',0,1,0),
     (86,'金砖',1,0,0,0,0,0,1000,3,0,'巨富商贾将黄金熔炼成金砖，以便保存。熔炼可获得黄金100万。','',1,0,5,'',0,1,0),
     (87,'粮食辎重包',1,0,0,0,0,0,10,3,0,'军队存放粮食的辎重包，打开后能获得10万粮食。','',1,0,7,'',0,1,0),
     (88,'木材辎重包',1,0,0,0,0,0,10,3,0,'军队存放木材的辎重包，打开后能获得10万木材。','',1,0,7,'',0,1,0),
     (89,'石料辎重包',1,0,0,0,0,0,10,3,0,'军队存放石料的辎重包，打开后能获得10万石料。','',1,0,7,'',0,1,0);
