     (95,'灰色装备匣',1,8,0,0,0,0,10,3,0,'灰色的装备匣，打开后能获得一件粗糙的将领装备。','',1,0,0,'',0,1,0),
     (96,'白色装备匣',1,2,0,0,0,0,30,3,0,'白色的装备匣，打开后能获得一件普通的将领装备。','',1,0,0,'',0,1,0),
     (97,'绿色装备匣',1,1,0,0,0,0,90,3,0,'绿色的装备匣，打开后能获得一件精良的将领装备。','',1,0,0,'',0,1,0),
     (101,'头部装备匣',1,2,0,0,0,0,40,3,0,'打开后获得一个头部装备。越好的装备出现的几率越小。','',1,0,5,'',0,1,0),
     (102,'颈部装备匣',1,2,0,0,0,0,30,3,0,'打开后获得一个颈部装备。越好的装备出现的几率越小。','',1,0,5,'',0,1,0);
