     (110,'饰品装备匣',1,2,0,0,0,0,60,3,0,'打开后获得一个饰品装备。越好的装备出现的几率越小。','',1,0,5,'',0,1,0),
     (111,'武器装备匣',1,2,0,0,0,0,75,3,0,'打开后获得一个武器装备。越好的装备出现的几率越小。','',1,0,5,'',0,1,0),
     (112,'坐骑缰绳',1,2,0,0,0,0,80,3,0,'使用后获得一个坐骑。越好的坐骑出现的几率越小。','',1,0,5,'',0,1,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (113,'练兵经验',1,5,5,0,0,5,8,1,0,'沙场老将带兵作战的经验总结，对新晋将领有一定帮助。对将领使用后，增加将领经验3000。','练兵经验是在将领界面中给将领加经验时使用。',0,0,8,'',0,0,0),
     (114,'兵法心得',1,1,1,5,5,1,30,1,0,'百战宿将对兵法的心得体会，凝聚了将领的一番心血。对将领使用后，增加将领经验30000。','兵法心得是在将领界面中给将领加经验时使用。',0,0,6,'',0,0,0),
     (115,'治军之道',1,0,0,3,8,0,100,1,0,'手握重兵的领军大将对治军和战争的领悟，是不可多的珍贵典藏。对将领使用后，增加将领经验300000。','治军之道是在将领界面中给将领加经验时使用。',0,0,4,'',0,0,0),
     (116,'猛火油罐',0,0,0,0,2,0,50,0,0,'猛火油罐，装满火油的瓦罐，向城内投掷火攻，猛烈的火势可烧毁大片建筑。对将领使用，在24小时内，该将领下一次占领城池的战斗胜利时，可随机降低目标城池1座建筑的等级1级，对官府和城墙无效。若一直没有参与占领战斗，则该效果24小时后自动失效。连续使用时间延长。','装满火油的瓦罐，向城内投掷火攻，猛烈的火势可烧毁大片建筑。对将领使用，在24小时内，该将领下一次占领城池的战斗胜利时，可随机降低目标城池1座建筑的等级1级，对官府和城墙无效。若一直没有参与占领战斗，则该效果24小时后自动失效。连续使用时间延长。',0,0,8,'',0,0,0),
     (117,'高级推恩令',1,0,0,0,1,0,500,0,0,'汉武帝颁布推恩令，令诸侯推私恩分封子弟为列侯。使用高级推恩令可将爵位暂时提升最多5级，但最高达到“关内侯”。爵位达到大夫以上才能使用。持续10天，连续使用时间延长。','',1,0,2,'',0,0,0),
     (118,'藏宝图',1,5,5,5,5,5,10,0,0,'标记有宝藏位置的藏宝地图，年代有些久远，字迹比较模糊。','听说客栈有智慧的长者可以鉴别此图...',0,0,8,'',0,0,0),
     (119,'宝藏匣',1,0,0,0,0,0,1,3,0,'深埋地底的宝藏匣，打开后可获得宝藏。在客栈鉴定宝藏，获得宝藏坐标报告。在24小时内前往该地点，采集1小时后，可获得宝藏匣。','',1,0,6,'',0,0,0),
     (120,'商队契约',1,0,2,5,20,0,50,0,0,'定时运送资源，可让几个城池定时向目标运送资源。需要占用市场的商队。每次运送上限不超过城池中市场中1支商队所能运输的上限（10万~100万）。','获得3天自动运输特权。连续使用时间延长。',1,0,7,'',0,0,0),
     (121,'休假符',0,0,0,0,0,0,1,0,0,'使用后可休假3天。','',1,0,0,'',0,0,0),
     (122,'高级休假符',0,0,0,0,0,0,2,0,0,'使用后可休假10天。','',1,0,0,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (124,'推恩令',1,0,0,1,5,0,150,0,0,'汉武帝颁布推恩令，令诸侯推私恩分封子弟为列侯。使用推恩令可将爵位暂时提升最多2级，但最高达到“大庶长”。持续3天，连续使用时间延长。','',1,0,3,'',0,0,0),
     (125,'韩信三篇上部',1,2,10,10,20,2,5,1,0,'韩信点兵，多多益善。韩信兵法中记载了韩信练兵的心得，依照此法练兵，可迅速练出精悍士卒。因吕氏乱政，兵法大部分遗失，仅流传下三篇，此为上部。使用后可缩短当前训练队列时间2小时。可连续使用。','韩信三篇上部是在军营中对训队列加速的时候使用。练',0,0,6,'',0,0,0),
     (133,'军令状',1,0,2,10,15,0,30,0,0,'立下军令状，在战场中消灭敌军可获得3倍战场荣誉，持续24小时。连续使用时间延长。','',1,0,8,'',0,0,0),
     (134,'赦免文书',1,0,1,5,10,0,50,0,0,'赦免因战场失利而导致名誉扫地的责任。使用后立即将所有小于0的战场荣誉变为0。','',1,0,8,'',0,0,0),
     (135,'援军令',1,0,8,12,6,1,3,0,0,'调遣援军前来支援，立即补充战场中的军队。战场结束后，未损失的援军会自动离开。雇佣的援军数量越多，需要消耗的援军令越多。','援军令是在战场中调遣援军时使用。',0,0,8,'',0,0,0),
     (136,'急行军令',1,0,10,15,6,1,5,1,0,'命令作战的军队急行军，立即缩短战场中军队的行军时间为10秒。','急行军令是在战场中加速军队时使用。',0,0,8,'',0,0,0),
     (137,'讨伐令',1,5,10,15,6,5,3,0,0,'讨伐令，奉天子诏令，讨伐四方不臣者。创建大于10级的剧情战场，需要消耗讨伐令。创建的战场等级越高，需要消耗的讨伐令越多。','讨伐令是在创建11级以上的剧情战场时使用。',0,0,8,'',0,0,0),
     (138,'请战书',1,1,6,15,10,0,20,0,0,'立即重置剧情战场参战次数为0，重新拥有5次参加剧情战场的机会。','',1,0,8,'',0,0,0),
     (139,'太平要术',1,0,0,0,0,0,25,0,0,'传说中黄巾起义首领张角入山采药，遇南华老仙，授之《太平要术》，遂创太平道，开始散施符水，念咒治病，还能呼风唤雨，信徒发展为数十万人。使用后立即增加当前城池人口的10%。不超过人口上限。','',1,0,0,'',0,0,0),
     (140,'信鸽',1,5,10,10,5,5,3,0,0,'斥候通过信鸽来传递远方的情报，在战场中侦察其他据点的敌军兵力情况，需要使用信鸽。在同一据点内的敌军可以直接查看，无需侦察。','信鸽是在战场中侦察其他据点的敌军时使用。',0,0,8,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (141,'委托文书',0,-1,8,15,10,1,10,0,0,'在客栈发布委托任务需要消耗1个委托文书。','委托文书是在客栈中发布委托任务时使用。',0,0,8,'',0,0,0),
     (142,'巡查令',1,0,0,0,0,0,50,0,0,'增派将领四处巡查，维护治安。使用后可增加3个将领历练名额，使同时历练的将领人数达到5个。效果持续3天，连续使用时间延长','',1,0,0,'',0,0,0),
     (143,'通关文书',1,0,0,0,0,0,5,1,0,'对正在历练中的将领使用，该将领剩余历练时间减少30%，至少缩短30分钟。','通关令是在招贤观中对正在历练中的将领使用的',0,0,0,'',0,0,0),
     (144,'急召令',1,0,0,0,0,0,5,1,0,'急召令是在招贤馆中对正在历练返途的将领使用的，使用后，该将领立即回到出发城池的招贤馆中。','急召令是在招贤馆中对正在历练返途的将领使用的',0,0,0,'',0,0,0),
     (145,'武器架',1,0,2,10,15,0,90,0,0,'使用武器架后永久增加5格装备栏，可多次使用，最多可扩展装备栏到500格','',1,0,5,'',0,0,0),
     (146,'高级武器架',1,0,2,10,15,0,90,0,0,'使用高级武器架后永久增加50格装备栏，可多次使用，最多可扩展装备栏到500格','',1,0,1,'',0,0,0),
     (148,'聚魂幡',1,0,0,0,0,0,60,0,0,'使用时选择1个武魂碎片，可直接获得该将领的武魂。','',1,0,0,'',0,0,0),
     (149,'引魂香',1,0,0,0,0,0,5,0,0,'使用时选择1张将领画像，可获得该将领的武魂碎片，幸运时可直接获得武魂。','通关令是在招贤观中对正在历练中的将领使用的',0,0,0,'',0,0,0),
     (151,'护命金丹',1,0,2,5,15,0,50,0,0,'传说华佗所传秘方制成的丹药，将领重伤治疗时使用，可以恢复将领体力100%。','传说华佗所传秘方制成的丹药，可医百病！',0,0,0,'',0,0,0),
     (152,'铜钱',1,0,0,0,0,0,0,127,0,'铜币，用来买东西。','铜币，用来买东西。',0,0,0,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (153,'宝珠匣',1,0,0,0,0,0,100,3,0,'里面装满了各种宝珠，有几率可以开出镶嵌宝珠！','里面装满了各种宝珠，有几率可以开出镶嵌宝珠！',1,0,0,'',0,1,0),
     (154,'求贤诏',1,0,0,5,10,0,60,0,0,'昔日，姜太公立钩而钓天下，文王大礼往见；魏侯生不以贫而受财，信陵君从车虚左亲迎。欲成大事，岂可无定国安邦之能臣，运筹帷幄之士？周公吐哺，天下归心。使用后可以增加3个结交名将的位置，效果持续7天，连续使用时间延长。','求贤诏需在结交名将时使用',1,0,0,'',0,0,0),
     (155,'炼化鼎',1,0,0,5,10,0,50,0,0,'据说鼎内蕴含亿万炼化之法，可炼化天地万物。用于炼化套装，炼化后装备将获得附加属性。','炼化鼎是在英雄装备界面用于炼化套装的。',0,0,0,'',0,0,0),
     (156,'自荐状',1,0,0,0,0,0,0,3,0,'能臣侍明君，凡有志之士都希望找到一位贤明的君主，在其麾下大显身手。现在有一名勇武70，智谋70，内政70的杰出武将慧眼识君，并向您毛遂自荐。打开自荐状，你便能拥有他（她）。','能臣侍明君，凡有志之士都希望找到一位贤明的君主，在其麾下大显身手。现在有一名勇武70，智谋70，内政70的杰出武将慧眼识君，并向您毛遂自荐。打开自荐状，你便能拥有他（她）。',1,0,0,'',0,0,0),
     (157,'讨逆圣旨',1,0,0,0,0,0,80,0,0,'天子所亲书的讨逆檄文，使用后不经过宣战，立刻和其它君主进入战争状态，持续8小时。若不使用讨逆圣旨，则需要等待8小时后，才能进入战争。','讨逆圣旨是在对玩家宣战时使用的',0,0,0,'',0,0,0),
     (158,'誓师文书',1,0,0,0,0,0,50,0,0,'将领出征前所写的誓师文书，用来坚定将士的必胜信念。使用后立即将小于100的逐鹿中原积分变为100。','',1,0,0,'',0,0,0),
     (159,'幸运之钥',1,0,0,0,0,0,40,0,0,'金光闪闪的幸运之钥，让幸运环绕在你的周围，拥有“幸运之钥”的人，可以开启一次“幸运宝匣”。','幸运之钥在开启"幸运宝匣"时使用',0,0,0,'',0,0,0),
     (160,'讨逆礼匣',1,0,0,0,0,0,100,3,0,'诸葛军师讨伐南蛮，赠此匣犒赏出征三军','',1,0,0,'',0,0,0),
     (161,'破虏礼匣',1,0,0,0,0,0,100,3,0,'诸葛军师首擒孟获，赠此匣奖赏有功将士','',1,0,0,'',0,0,0),
     (162,'平蛮礼匣',1,0,0,0,0,0,100,3,0,'诸葛军师七擒孟获，赠此匣安抚南蛮众军','',1,0,0,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (163,'镇南礼匣',1,0,0,0,0,0,100,3,0,'诸葛军师大胜南蛮班师回朝，赠此匣奖赏三军','',1,0,0,'',0,0,0),
     (164,'沙场令',1,0,0,0,0,0,5,0,0,'醉卧沙场君莫笑，古来征战几人还。使用后可继续参加5场沙场争霸','在沙场中使用',0,0,0,'',0,0,0),
     (165,'高级青囊书',1,0,0,5,15,0,99,0,0,'增强军队的战场救治能力，让战斗中损失的军队有60%成为额外的伤兵，进入伤兵营等待治疗。效果持续24小时，连续使用时间延长。','',1,0,2,'',0,1,0),
     (166,'高级徭役令',1,0,2,5,20,0,99,0,0,'向百姓征发徭役，驱使大量劳力用于城池建设。使用后可增加5个建造队列，使城池可以同时建造7个建筑。效果持续3天，连续使用时间延长。','',1,0,3,'',0,1,0),
     (167,'大型金锭',1,0,0,0,0,0,99,3,0,'诸侯熔炼的大型金锭，用于进贡朝廷，打开后能获得1000万黄金。','',1,0,0,'',0,1,0),
     (168,'大型粮食辎重匣',1,0,0,0,0,0,99,3,0,'军队存放粮食的大型粮食辎重匣，打开后能获得1000万粮食。','',1,0,0,'',0,1,0),
     (169,'大型木材辎重匣',1,0,0,0,0,0,99,3,0,'军队存放木材的大型木材辎重匣，打开后能获得1000万木材。','',1,0,0,'',0,1,0),
     (170,'大型石料辎重匣',1,0,0,0,0,0,99,3,0,'军队存放石料的大型石料辎重匣，打开后能获得1000万石料。','',1,0,0,'',0,1,0),
     (171,'大型铁锭辎重匣',1,0,0,0,0,0,99,3,0,'军队存放铁锭的大型铁锭辎重匣，打开后能获得1000万铁锭。','',1,0,0,'',0,1,0),
     (172,'人口资源卡',1,0,0,0,0,0,99,3,0,'诸侯用于征召士兵的凭证，使用后能获得当前城池人口上限的数量。','',1,0,0,'',0,1,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (201,'化石粉',1,0,20,15,5,0,5,0,0,'化石粉可拆卸和溶掉镶嵌宝珠!','化石粉可以完好无损的把宝珠从装备上拆卸下来',0,0,6,'',0,0,0),
     (202,'巧手符',1,0,5,10,0,0,30,0,0,'材料合成道具,提高材料合成成功率','巧手符，可以提高材料合成成功率',0,0,3,'',0,0,0),
     (203,'天工符',1,0,0,5,10,0,20,0,0,'写满神秘咒文的符纸，在强化将领装备时一起使用，可以提高强化成功率','天工符，在强化将领装备时一起使用，可以提高强化成功率',0,0,5,'',0,0,0),
     (204,'乾坤宝珠',1,0,0,5,15,0,30,0,0,'闪动着微光的神秘宝珠，在强化将领装备的时候一起使用，可以保证装备强化失败时保护装备不会受到任何损失。','乾坤宝珠，在强化将领装备时一起使用',0,0,3,'',0,0,0),
     (205,'强化宝珠',1,0,0,5,15,0,20,4,0,'用于强化装备，可以提高装备强化等级','强化宝珠，用于强化装备',0,0,4,'',0,0,0),
     (206,'金刚钻',1,0,5,10,0,0,10,0,0,'使用金刚钻在装备上打孔，可以在装备上镶嵌宝珠，提高装备的属性','金刚钻，用于装备打孔',0,0,0,'',0,0,0),
     (207,'高级金刚钻',1,0,0,5,10,0,50,0,0,'高级金刚钻可以在装备上打出更多的孔，以便镶嵌更多的宝珠','高级金刚钻，用于装备打孔',0,0,0,'',0,0,0),
     (209,'玄铁',1,0,5,10,0,0,10,4,0,'玄铁,强化宝珠合成材料之一','玄铁,用于合成材料',0,0,6,'',0,0,0),
     (210,'犀角',1,0,5,10,0,0,10,4,0,'犀角,强化宝珠合成材料之一','犀角,用于合成材料',0,0,6,'',0,0,0),
     (211,'凤羽',1,0,5,10,0,0,10,4,0,'凤羽,强化宝珠合成材料之一','凤羽,用于合成材料',0,0,6,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (212,'伯乐符',1,0,0,5,15,0,20,0,0,'相传是伯乐留下的宝物，在强化坐骑时一起使用，可以提高强化成功率','伯乐符，在强化坐骑一起使用，可以提高强化成功率',0,0,0,'',0,0,0),
     (213,'师皇针',1,0,0,5,10,0,30,0,0,'当年马师皇用的宝针，救治过无数战马，在强化坐骑的时候一起使用，可以保证坐骑强化失败时保护坐骑不会受到任何损失','师皇针，可以和强化坐骑一起使用',0,0,0,'',0,0,0),
     (214,'灵通甘草',1,0,0,5,15,0,20,4,0,'用于强化坐骑，可以提高坐骑等级','灵通甘草，用于强化坐骑',0,0,4,'',0,0,0),
     (251,'铁骑兵符',1,0,0,0,0,0,60,3,0,'得兵权者得天下，使用此符可迅速召集铁骑2000骑。','',1,0,0,'',0,1,0),
     (252,'车弩兵符',1,0,0,0,0,0,60,3,0,'得兵权者得天下，使用此符可迅速召集车弩1500乘。','',1,0,0,'',0,1,0),
     (253,'投石兵符',1,0,0,0,0,0,60,3,0,'得兵权者得天下，使用此符可迅速召集投石1000乘。','',1,0,0,'',0,1,0),
     (254,'冲车兵符',1,0,0,0,0,0,60,3,0,'得兵权者得天下，使用此符可迅速召集冲车1200乘。','',1,0,0,'',0,1,0),
     (255,'三军兵符',1,0,0,0,0,0,10,3,291,'得兵权者得天下，使用此符可随机召集一种兵种5000。','得兵权者得天下，使用此符可随机召集一种兵种5000',1,0,0,'',1,1,0),
     (256,'特种兵符',1,0,0,0,0,0,1,3,291,'得兵权者得天下，使用此符可随机召集一种特种兵种5000。','得兵权者得天下，使用此符可随机召集一种特种兵种5000。',1,0,0,'',1,1,0),
     (300,'1级统率镶嵌宝珠',1,0,0,0,2,0,10,4,0,'拥有一股神奇的力量，镶嵌在装备上能使人拥有更高的统率','镶嵌宝珠在镶嵌装备时使用',0,0,0,'1,1',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (301,'2级统率镶嵌宝珠',1,0,0,0,2,0,25,4,0,'拥有一股神奇的力量，镶嵌在装备上能使人拥有更高的统率','镶嵌宝珠在镶嵌装备时使用',0,0,0,'1,2',0,0,0),
     (302,'3级统率镶嵌宝珠',1,0,0,0,1,0,50,4,0,'拥有一股神奇的力量，镶嵌在装备上能使人拥有更高的统率','镶嵌宝珠在镶嵌装备时使用',0,0,0,'1,3',0,0,0),
     (303,'4级统率镶嵌宝珠',1,0,0,0,1,0,100,4,0,'拥有一股神奇的力量，镶嵌在装备上能使人拥有更高的统率','镶嵌宝珠在镶嵌装备时使用',0,0,0,'1,4',0,0,0),
