     (1001,'黄巾礼匣',1,0,0,0,1,0,20,3,0,'黄巾起义期间，黄巾军劫掠了大量财物珍宝。打开后，可获得黄巾军的宝藏和装备。','',1,0,0,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (1002,'官渡礼匣',0,0,0,0,0,0,20,3,0,'官渡之战时期，曹军和袁军都锻造了大量的武器装备。打开后，可获得袁曹两军的物资和装备。','',1,0,0,'',0,0,0),
     (1003,'十常侍礼匣',0,0,0,0,0,0,25,3,0,'十常侍把持朝政，横征暴敛，聚敛了大量的财物。打开后，可获得十常侍的宝藏和汉室奖励给各路平乱英雄的装备。','',1,0,0,'',0,0,0),
     (1004,'讨伐董卓礼匣',1,0,0,0,0,0,25,3,0,'董卓生性残虐，荼毒天下，人人得而诛之。打开后，可获得西凉军的物资和装备。','',1,0,0,'',0,0,0),
     (1005,'千里走单骑礼匣',0,0,0,0,0,0,30,3,0,'关羽封金挂印，千里走单骑，留下了千古美名。打开后，可获得当日关羽拒绝的财物和关羽的装备。','',1,0,0,'',0,0,0),
     (1006,'逐鹿中原礼匣',0,0,0,0,0,0,30,3,0,'东汉末年，天下大乱，各路诸侯纷纷揭竿而起，群雄逐鹿中原。打开后，可获得各路诸侯聚集的财物和装备。','',1,0,0,'',0,0,0),
     (1007,'三让徐州礼匣',0,0,0,0,0,0,35,3,0,'曹操以为父报仇之名，发兵攻徐州；徐州牧陶谦三让徐州于备，备均辞而不纳。打开后，可获得刘陶联军和曹军的物资装备。','',1,0,0,'',0,0,0),
     (1008,'凤仪亭礼匣',0,0,0,0,0,0,35,3,0,'凤仪亭董卓怒执戟刺布，从此父子不和。王允说动吕布，出计诛除董卓。打开后，可获得汉室财物和貂蝉之物。','',1,0,0,'',0,0,0),
     (1009,'虎符匣',1,0,0,0,0,0,100,3,0,'存放青铜虎符、白银虎符和黄金虎符的宝匣，打开可随机获得任意一种虎符。','',1,0,0,'',0,0,0),
     (1010,'陷阵战鼓匣',1,0,0,0,0,0,100,3,0,'存放下品陷阵战鼓、中品陷阵战鼓、上品陷阵战鼓的宝匣，打开可随机获得一种陷阵战鼓。','',1,0,0,'',0,0,0),
     (1011,'醍醐汤匣',1,0,0,0,0,0,100,3,0,'存放普通醍醐汤、中品醍醐汤、上品醍醐汤的宝匣，打开可随机获得一种醍醐汤','',1,0,0,'',0,0,0);
