     (10009,'超值城主礼包',1,0,0,0,0,0,2000,3,0,'超值城主礼包，内有“神农锄”5、“鲁班斧”5、“开山锤”5、“玄铁炉”5、“陷阵战鼓”5、“八卦阵图”5、“墨家残卷”50、“墨家图纸”20、“墨家典籍”5、“木牛流马”10、“免战牌”2、“锦囊”10、“洗髓丹”2、“招贤榜”10、“迁城令”1。','',1,0,0,'',0,0,0),
