     (10012,'高级生产礼包',1,0,0,0,0,0,630,3,0,'高级生产礼包，内有“高级神农锄”1、“高级鲁班斧”1、“高级开山锤”1、“高级玄铁炉”1、“高级税吏鞭”1、“建筑图纸”3。','',1,0,0,'',0,0,0),
