     (10017,'钥匙链',1,0,0,0,0,0,100,3,0,'打开后可获得10把钥匙，大部分是青铜钥匙，运气好可能获得白银钥匙、黄金钥匙。','',1,0,0,'',0,0,0),
     (10018,'建设礼包',1,0,0,0,0,0,450,3,0,'建设礼包:内有"粮食辎重匣"1,"木材辎重匣"1,"石料辎重匣"1,"铁锭辎重匣"1。','',1,0,0,'',0,1,0),
     (10019,'城主礼包',1,0,0,0,0,0,2000,3,0,'城主礼包:内有“神农锄”5、“鲁班斧”5、“开山锤”5、“玄铁炉”5、“税吏鞭”5、“陷阵战鼓”5、“八卦阵图”5、“鲁班草图”10、“鲁班书册”5、“鲁班秘录”2、“墨家图纸”10、“墨家古籍”5、“墨家秘笈”2、“免战牌”1、“洗髓丹”2、“招贤榜”12。','',1,0,0,'',0,0,0),
     (10050,'拜月装备匣',0,0,0,0,0,0,2,3,0,'使用后可获得任意1件拜月装备。','',1,0,0,'',0,0,0),
     (10052,'愿望礼包',0,0,0,0,0,0,2,3,1,'《热血三国》给于充值玩家的额外惊喜！打开有机会获得超值宝物或元宝，还有极品装备哦！','',1,0,0,'',1,0,0),
     (10056,'生肖套装匣',0,0,0,0,0,0,2,3,6,'使用后可获得12种生肖玉牌中的任意一块，凑齐指定的玉牌可在活动任务中兑换元宝或宝物或装备奖励。','',1,0,0,'',1,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (10104,'拴牛缰绳',0,0,0,0,0,0,1,3,7,'拴牛用的绳子。使用后有机会获得资源、礼金、宝物、金牛装备。','',1,0,0,'',1,0,0),
     (10138,'备战的证明',1,0,0,0,0,0,0,0,0,'东汉末年，黄巾作乱，群雄四起，洛阳岌岌可危。得洛阳者得天下！这是备战洛阳的勇士最好的证明。','不可直接使用，可在新版本开放后兑换“备战洛阳的勇士”成就。',0,0,0,'',0,0,0),
     (10152,'蜂王蜜膏',1,0,0,0,0,0,1,0,0,'蜂王蜜膏，由珍贵药材炼制而成。对将领使用后，永久增加将领统率1点。每个将领最多可使用50个。','蜂王蜜膏是在将领界面给将领加统率属性时使用的',0,0,0,'',0,0,0),
     (10153,'灵芝玉露',1,0,0,0,0,0,1,0,0,'灵芝玉露，由珍贵药材炼制而成。对将领使用后，永久增加将领内政1点。每个将领最多可使用50个。','灵芝玉露是在将领界面给将领加内政属性时使用的',0,0,0,'',0,0,0),
     (10154,'蛇胆神丸',1,0,0,0,0,0,1,0,0,'蛇胆神丸，由珍贵药材炼制而成。对将领使用后，永久增加将领智谋1点。每个将领最多可使用50个。','蛇胆神丸是在将领界面给将领加智谋属性时使用的',0,0,0,'',0,0,0),
     (10155,'虎骨灵丹',1,0,0,0,0,0,1,0,0,'虎骨灵丹，由珍贵药材炼制而成。对将领使用后，永久增加将领勇武1点。每个将领最多可使用50个。','虎骨灵丹是在将领界面给将领加勇武属性时使用的',0,0,0,'',0,0,0),
     (10158,'高级建筑图纸',1,0,0,0,0,0,1,0,0,'高级建筑图纸，只能对普通城池（非名城，非主城）使用，使用后当前城池的城外资源建筑可升级至10级以上，上限为12级，持续12小时。','',1,0,0,'',0,0,0),
     (10166,'备战宝匣',1,0,0,0,0,0,1,3,2,'备战宝匣，打开有可能获得灵通甘草、镶嵌宝珠、坐骑装备马盔和马铠。','',1,0,0,'',1,0,0),
     (10167,'勤政礼包',1,0,0,0,0,0,1,3,4,'勤政礼包，打开有可能获得平定黄巾勋章、蓝色织女套装部件、坐骑装备马鞍。','',1,0,0,'',1,0,0),
     (10168,'出战锦囊',1,0,0,0,0,0,1,3,0,'出战锦囊，打开有可能获得曹军官渡勋章、蓝色牛郎套装部件、坐骑装备马绳。','',1,0,0,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (10169,'百战礼匣',1,0,0,0,0,0,1,3,5,'百战礼匣，打开有可能获得袁军官渡勋章、蓝色亡灵套装部件、坐骑装备马蹄铁。','',1,0,0,'',1,0,0),
     (10215,'勇士召唤令',1,0,0,0,0,0,100,3,25,'使用后在招贤馆召唤到一个拥有高级天赋的“热血勇士”将领。该将领不会被俘虏，忠诚度低于60可能逃亡，升级到一定等级时可在活动任务中领取额外的奖励。','',1,0,0,'',1,0,0),
     (10269,'枭姬的礼赞',1,0,0,0,0,0,30,3,49,'孙夫人为感谢帮其寻回传家弓的勇士，特意献上的礼物，打开将有机会获得亡灵套装匣，神牛套装，名将套装最新部件，强化7级射日弓和蜀国神秘果子。','',1,0,0,'',1,0,0),
     (10272,'王的传说',1,0,0,0,0,0,500,3,52,'使用后可100%获得一件王之系列绿色装备（王之坠链、王之肩甲、王之披风、王之腰带、王之护腕、王之战靴、王之玉佩、王之坐骑、王之大刀、王之戒指、王之头盔、王之铠甲）。','',1,0,0,'',1,0,0),
     (10273,'亡灵故事',1,0,0,0,0,0,800,3,53,'使用后可100%获得一件亡灵套装部件（亡灵头盔、亡灵项链、亡灵护肩、亡灵战袍、亡灵披风、亡灵腰带、亡灵护手、亡灵扳指、亡灵佩饰、亡灵血刃、亡灵战靴、亡灵兽）。','',1,0,0,'',1,0,0),
     (10274,'武士传奇',1,0,0,0,0,0,1000,3,54,'使用后可100%获得一件武士套装部件（暗夜风暴、血色命运、神的旨意、光的圣衣、风的吟唱、夜的愤怒、剑的沉默、影子步行、银月之光、洁玉之气、止战之殇、武士的宠儿）。','',1,0,0,'',1,0,0),
     (10275,'长坂事迹',1,0,0,0,0,0,2000,3,55,'使用后可100%获得一件名将套装部件（召虎头盔、百翎护颈、长坂护肩、麦城护甲、仲谋披风、麒麟护腰、王佐护手、伯约护腿、武侯羽扇、梨花枪）。','',1,0,0,'',1,0,0),
     (10276,'七月的传说',1,0,0,0,0,0,50,3,10,'使用后可获得任意一件道具（平定黄巾勋章、袁军官渡勋章、曹军官渡勋章、宝珠匣、迁城令、白银钥匙、白银礼匣、黄金钥匙、黄金礼匣、韩信三篇、建筑图纸、灵通甘草、王的传说、亡灵故事、武士传奇、长坂事迹、亡灵套装匣）。','',1,0,0,'',1,0,0),
     (10277,'阿依努尔的传说',1,0,0,0,0,0,50,0,56,'她的名字，叫阿依努尔，月光的意思。','她的名字，叫阿依努尔，月光的意思。',0,0,0,'',1,0,0),
     (10288,'一线消息',1,0,0,0,0,0,20,0,67,'与曹军交锋几次才终于找到那个马贼，可她说生擒的女子并非所描述的阿依努尔。难道她早已死去？这卷卷黄沙中到底埋藏着多少古老的秘密？或许时间会告诉我们答案！有效制止日期为2010年8月25日。','与曹军交锋几次才终于找到那个马贼，可她说生擒的女子并非所描述的阿依努尔。难道她早已死去？这卷卷黄沙中到底埋藏着多少古老的秘密？或许时间会告诉我们答案！有效制止日期为2010年8月25日。',0,0,0,'',1,0,0);
