     (18010,'黄巾锦匣',1,0,0,0,0,0,10,3,60,'打开可以获得初级成长卷、传音符、急行军令、金刚钻、文曲星符、武曲星符、智多星符、陷阵战鼓、八卦阵图、1级统率镶嵌宝珠、1级勇武镶嵌宝珠、1级智谋镶嵌宝珠、1级内政镶嵌宝珠、神农锄、玄铁炉、开山锤、鲁班斧、名将部件。','',1,0,0,'',1,0,0),
     (18011,'黄巾尊匣',1,0,0,0,0,0,10,3,60,'打开可以获得初级成长卷、中级成长卷、急行军令、金刚钻、文曲星符、武曲星符、智多星符、陷阵战鼓、八卦阵图、2级统率镶嵌宝珠、2级勇武镶嵌宝珠、2级智谋镶嵌宝珠、2级内政镶嵌宝珠、名将部件。','',1,0,0,'',1,0,0),
     (18020,'十常侍锦匣',1,0,0,0,0,0,10,3,62,'打开可以获得初级成长卷、文曲星符、武曲星符、智多星符、陷阵战鼓、八卦阵图、2级统率镶嵌宝珠、2级勇武镶嵌宝珠、2级智谋镶嵌宝珠、2级内政镶嵌宝珠、鲁班残页、鲁班便笺、墨家散页、墨家图纸、名将部件。','',1,0,0,'',1,0,0),
     (18021,'十常侍尊匣',1,0,0,0,0,0,10,3,62,'打开可以获得初级成长卷、中级成长卷、文曲星符、武曲星符、智多星符、3级统率镶嵌宝珠、3级勇武镶嵌宝珠、3级智谋镶嵌宝珠、3级内政镶嵌宝珠、鲁班残页、鲁班便笺、墨家散页、墨家图纸、名将部件。','',1,0,0,'',1,0,0),
     (18030,'讨董锦匣',1,0,0,0,0,0,10,3,61,'打开可以获得初级成长卷、中级成长卷、迁城令、金刚钻、文曲星符、武曲星符、智多星符、陷阵战鼓、八卦阵图、3级统率镶嵌宝珠、3级勇武镶嵌宝珠、3级智谋镶嵌宝珠、3级内政镶嵌宝珠、鲁班草图、墨家图纸、建筑图纸、金疮药、名将部件。','',1,0,0,'',1,0,0),
     (18031,'讨董尊匣',1,0,0,0,0,0,10,3,61,'打开可以获得高级成长卷、中级成长卷、迁城令、金刚钻、文曲星符、武曲星符、智多星符、4级统率镶嵌宝珠、4级勇武镶嵌宝珠、4级智谋镶嵌宝珠、4级内政镶嵌宝珠、<font color="#FF0000">孙子兵法3</font>、军令3、强化宝珠、名将部件。','',1,0,0,'',1,0,0),
