     (154010,'2星神将魂晶',0,0,0,0,0,0,1888,3,10841,'封印有神将的魂魄，选择对应名将使用后，将得到一个2星的同名神将。','封印有神将的魂魄，选择对应名将使用后，将得到一个2星的同名神将。',1,0,0,'',1,0,0),
     (154011,'3星神将魂晶',0,0,0,0,0,0,1888,3,10841,'封印有神将的魂魄，选择对应名将使用后，将得到一个3星的同名神将。','封印有神将的魂魄，选择对应名将使用后，将得到一个3星的同名神将。',1,0,0,'',1,0,0),
     (160001,'特制神农锄',1,0,0,0,0,0,8,2,0,'提高名城对城池粮食产量的25%，持续8小时。连续使用时间延长。跨服专用。','',1,0,8,'',0,0,0),
     (160002,'特制鲁班斧',1,0,0,0,0,0,8,2,0,'提高名城对城池木材产量的25%，持续8小时。连续使用时间延长。跨服专用。','',1,0,8,'',0,0,0),
     (160003,'特制开山锤',1,0,0,0,0,0,8,2,0,'提高名城对城池石料产量的25%，持续8小时。连续使用时间延长。跨服专用。','',1,0,8,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (160004,'特制玄铁炉',1,0,0,0,0,0,8,2,0,'提高名城对城池铁锭产量的25%，持续8小时。连续使用时间延长。跨服专用。','',1,0,8,'',0,0,0),
     (160005,'特制陷阵战鼓',1,0,0,0,0,0,10,0,0,'冲锋陷阵时擂响的战鼓，士兵闻之即士气大振，必勇猛向前，攻无不克。军队攻击增加20%，持续8小时。连续使用时间延长。','军队攻击增加20%，持续8小时。连续使用时间延长。',1,0,6,'',0,0,0),
     (160006,'特制八卦阵图',1,0,0,0,0,0,10,0,0,'以周易八卦推演而成的作战阵法，防守时不动如山，可当十万精兵。军队防御增加20%，持续8小时。连续使用时间延长。','军队防御增加20%，持续8小时。连续使用时间延长。',1,0,6,'',0,0,0),
     (160007,'普通迁城令',1,0,0,0,0,0,30,0,0,'将城池随机迁徙到一个己方阵营的县城或郡城中。使用时不能有军队在外。','将城池随机迁徙到一个己方阵营的县城或郡城中',1,0,8,'',0,0,0),
     (160008,'精装青囊书',1,0,0,0,0,0,90,0,0,'增强军队的战场救治能力，让战斗中损失的军队有30%成为额外的伤兵，进入伤兵营等待治疗。效果持续8小时，连续使用时间延长。','增强军队的战场救治能力，让战斗中损失的军队有30%成为额外的伤兵，进入伤兵营等待治疗。效果持续8小时，连续使用时间延长。',1,0,2,'',0,0,0),
     (160009,'特制徭役令',1,0,0,0,0,0,50,0,0,'向百姓征发徭役，驱使大量劳力用于城池建设。使用后增加3个建造队列，使用权城池可以同时建造5个建筑。效果持续24小时，连续使用时间延长。','使用后增加3个建造队列，使用权城池可以同时建造5个建筑。效果持续3天，连续使用时间延长。',1,0,3,'',0,0,0),
     (160010,'特制典民令',1,0,0,0,0,0,50,0,0,'吸纳大批失去土地的流民作为城池居民。使用后增加人口数量为城池人口上限的10%，最少增加1000人。','使用后增加人口数量为城池人口上限的10%，最少增加1000人。',1,0,2,'',0,0,0),
     (160012,'韩信点兵术',1,0,0,0,0,0,30,1,0,'韩信将兵，多多益善。使用后可缩短当前训练队列剩余时间的50%。最少缩短30分钟。','韩信将兵，多多益善。使用后可缩短当前训练队列剩余时间的50%。',0,0,6,'',0,0,0),
     (160013,'鲁班经残本',1,0,0,0,0,0,5,1,0,'记录了鲁班建筑经验的破损书页。使用后缩短一项建筑任务的时间15分钟。','使用后缩短一项建筑任务的时间15分钟。',0,0,8,'',0,0,0),
     (160014,'鲁班经拓本',1,0,0,0,0,0,10,1,0,'记录了鲁班建筑心得的简短纸片。使用后缩短一项建筑任务的时间1小时。','使用后缩短一项建筑任务的时间1小时。',0,0,7,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (160015,'鲁班经全本',1,0,0,0,0,0,20,1,0,'记录了鲁班建筑图样，线条有些潦草。使用后缩短一项建筑任务的时间2小时30分钟。','使用后缩短一项建筑任务的时间2小时30分钟。',0,0,6,'',0,0,0),
     (160016,'特制迁城令',1,0,0,0,0,0,60,0,0,'将城池迁徙到指定的一个己方阵营的县城或郡城中。使用时不能有军队在外。','将城池迁徙要指定的一个己方阵营的县城或郡城中',1,0,2,'',0,0,0),
     (160017,'特制火药筒',1,0,0,0,0,0,20,1,0,'塞满火药的竹筒，点燃可炸毁大片建筑。拆除建筑使用火药筒，可以立即将该建筑完全拆除，使其成为空地。使用火药筒拆除建筑，将无法回收资源。不能对官府使用。','拆除建筑使用火药筒，可以立即将该建筑完全拆除，使其成为空地。使用火药筒拆除建筑，将无法回收资源。不能对官府使用。',0,0,4,'',0,0,0),
     (160018,'特制军令状',1,0,0,0,0,0,30,0,0,'立下军令状，在战场中消灭敌军可获得3倍赤壁功勋，持续8小时。连续使用时间延长。','立下军令状，在战场中消灭敌军可获得3倍战场荣誉，持续8小时。连续使用时间延长。',1,0,8,'',0,0,0),
     (160019,'冲锋号令',1,0,0,0,0,0,3,1,0,'命令作战的军队急行军。使用后缩短行军速度为剩余时间的1/3。','使用后缩短行军速度为剩余时间的1/3。',0,0,8,'',0,0,0),
     (160020,'特训信鸽',1,0,0,0,0,0,3,0,0,'斥候通过信鸽来传递远方的情报，在战场中侦察其他据点的敌军兵力情况，需要使用信鸽。使用后获得军队情报。','使用后获得军队情报。',0,0,8,'',0,0,0),
     (160021,'特制考工记',1,0,0,0,0,0,40,2,0,'先秦时期手工艺的专著，记录了各种手工业技术、工艺资料、生产管理和营建制度。跨服战场专用，可以让城池内所有建筑的建造消耗资源成本降低30%。效果持续8小时，连续使用时间延长。跨服专用。','',1,0,7,'',0,0,0),
     (160026,'上品八卦阵图',1,0,0,0,0,0,15,0,0,'赏赐给将领后，由该将领带领的军队防御增加30%，以周易八卦推演而成的作战阵法，防守时不动如山，可当十万精兵。不能与八卦阵图效果叠加，持续1小时。连续使用时间延长。','赏赐给将领后，由该将领带领的军队防御增加30%，以周易八卦推演而成的作战阵法，防守时不动如山，可当十万精兵。效果持续1小时。连续使用时间延长。',0,0,0,'',0,0,0),
     (160027,'中品八卦阵图',1,0,0,0,0,0,10,0,0,'赏赐给将领后，由该将领带领的军队防御增加20%，以周易八卦推演而成的作战阵法，防守时不动如山，可当十万精兵。不能与八卦阵图效果叠加，持续1小时。连续使用时间延长。','赏赐给将领后，由该将领带领的军队防御增加20%，以周易八卦推演而成的作战阵法，防守时不动如山，可当十万精兵。效果持续1小时。连续使用时间延长。',0,0,0,'',0,0,0),
     (160028,'下品八卦阵图',1,0,0,0,0,0,5,0,0,'赏赐给将领后，由该将领带领的军队防御增加10%，以周易八卦推演而成的作战阵法，防守时不动如山，可当十万精兵。不能与八卦阵图效果叠加，持续1小时。连续使用时间延长。','赏赐给将领后，由该将领带领的军队防御增加10%，以周易八卦推演而成的作战阵法，防守时不动如山，可当十万精兵。效果持续1小时。连续使用时间延长。',0,0,0,'',0,0,0);
