     (160029,'上品陷阵战鼓',1,0,0,0,0,0,15,0,0,'赏赐给将领后，由该将领带领的军队攻击增加30%，冲锋陷阵时擂响的战鼓，士兵闻之即士气大振，必勇猛向前，攻无不克。不能与陷阵战鼓效果叠加，持续1小时。连续使用时间延长。','赏赐给将领后，由该将领带领的军队攻击增加30%，冲锋陷阵时擂响的战鼓，士兵闻之即士气大振，必勇猛向前，攻无不克。效果持续1小时。连续使用时间延长。',0,0,0,'',0,0,0),
     (160030,'中品陷阵战鼓',1,0,0,0,0,0,10,0,0,'赏赐给将领后，由该将领带领的军队攻击增加20%，冲锋陷阵时擂响的战鼓，士兵闻之即士气大振，必勇猛向前，攻无不克。不能与陷阵战鼓效果叠加，持续1小时。连续使用时间延长。','赏赐给将领后，由该将领带领的军队攻击增加20%，冲锋陷阵时擂响的战鼓，士兵闻之即士气大振，必勇猛向前，攻无不克。效果持续1小时。连续使用时间延长。',0,0,0,'',0,0,0),
     (160031,'下品陷阵战鼓',1,0,0,0,0,0,5,0,0,'赏赐给将领后，由该将领带领的军队攻击增加10%，冲锋陷阵时擂响的战鼓，士兵闻之即士气大振，必勇猛向前，攻无不克。不能与陷阵战鼓效果叠加，持续1小时。连续使用时间延长。','赏赐给将领后，由该将领带领的军队攻击增加10%，冲锋陷阵时擂响的战鼓，士兵闻之即士气大振，必勇猛向前，攻无不克。效果持续1小时。连续使用时间延长。',0,0,0,'',0,0,0),
     (160040,'青铜虎符',1,0,0,0,0,0,5,0,0,'赏赐给将领，该将领的统率提高10%，不能与虎符效果叠加，持续1小时。连续使用时间延长。','青铜虎符是在将领界面中赏赐将领时使用。',0,0,0,'',0,0,0),
     (160041,'白银虎符',1,0,0,0,0,0,10,0,0,'赏赐给将领，该将领的统率提高20%，不能与虎符效果叠加，持续1小时。连续使用时间延长。','白银虎符是在将领界面中赏赐将领时使用。',0,0,0,'',0,0,0),
     (160042,'黄金虎符',1,0,0,0,0,0,15,0,0,'赏赐给将领，该将领的统率提高30%，不能与虎符效果叠加，持续1小时。连续使用时间延长。','黄金虎符是在将领界面中赏赐将领时使用。',0,0,0,'',0,0,0),
     (160043,'上品醍醐汤',1,0,0,0,0,0,15,0,0,'赏赐给将领，该将领内政增加20%，不能与文曲星符效果叠加，持续1小时。连续使用时间延长。','上品醍醐汤是在将领界面中赏赐将领时使用。',0,0,0,'',0,0,0),
     (160044,'中品醍醐汤',1,0,0,0,0,0,10,0,0,'赏赐给将领，该将领内政增加10%，不能与文曲星符效果叠加，持续1小时。连续使用时间延长。','中品醍醐汤是在将领界面中赏赐将领时使用。',0,0,0,'',0,0,0),
     (160045,'普通醍醐汤',1,0,0,0,0,0,5,0,0,'赏赐给将领，该将领内政增加5%，不能与文曲星符效果叠加，持续1小时。连续使用时间延长。','普通醍醐汤是在将领界面中赏赐将领时使用。',0,0,0,'',0,0,0),
     (160046,'上品醒神汤',1,0,0,0,0,0,15,0,0,'赏赐给将领，该将领智谋增加20%，不能与智多星符效果叠加，持续1小时。连续使用时间延长。','上品醒神汤是在将领界面中赏赐将领时使用。',0,0,0,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (160047,'中品醒神汤',1,0,0,0,0,0,10,0,0,'赏赐给将领，该将领智谋增加10%，不能与智多星符效果叠加，持续1小时。连续使用时间延长。','中品醒神汤是在将领界面中赏赐将领时使用。',0,0,0,'',0,0,0),
     (160048,'普通醒神汤',1,0,0,0,0,0,5,0,0,'赏赐给将领，该将领智谋增加5%，不能与智多星符效果叠加，持续1小时。连续使用时间延长。','普通醒神汤是在将领界面中赏赐将领时使用。',0,0,0,'',0,0,0),
     (160049,'上品虎骨汤',1,0,0,0,0,0,15,0,0,'赏赐给将领，该将领勇武增加20%，不能与武曲星符效果叠加，持续1小时。连续使用时间延长。','上品虎骨汤是在将领界面中赏赐将领时使用。',0,0,0,'',0,0,0),
     (160050,'中品虎骨汤',1,0,0,0,0,0,10,0,0,'赏赐给将领，该将领勇武增加10%，不能与武曲星符效果叠加，持续1小时。连续使用时间延长。','中品虎骨汤是在将领界面中赏赐将领时使用。',0,0,0,'',0,0,0),
     (160051,'普通虎骨汤',1,0,0,0,0,0,5,0,0,'赏赐给将领，该将领勇武增加5%，不能与武曲星符效果叠加，持续1小时。连续使用时间延长。','普通虎骨汤是在将领界面中赏赐将领时使用。',0,0,0,'',0,0,0),
     (160052,'名城契约',1,0,0,0,0,0,0,5,0,'上得天时，下得地势，中得人心。建久安之势，成长治之业。奖励给在赤壁之战中奋勇作战的勇士，只有那些得到大运势的人才有可能获得，向曹操欢呼吧！每个玩家只可获得一个。','建国必备物品，打开后可获得一座名城，在下一个版本中使用！',1,0,0,'',0,0,0),
     (161001,'调军令',1,0,0,0,0,0,5,7,0,'调遣援军前来支援，立即补充战场中的军队。战场结束后，未损失的援军领会自动离开。雇佣的援军越多，需要消耗的调军令越多。','调军令是在七擒孟获战场中调遣援军时使用的。',0,0,0,'',0,0,0),
     (161002,'急冲锋令',1,0,0,0,0,0,10,7,0,'命令作战的军队急冲锋，立即缩短战场中军队的行军时间为10秒。','急冲锋令是在七擒孟获战场中加速行军时使用的。',0,0,0,'',0,0,0),
     (161003,'誓师令',1,0,0,0,0,0,30,7,0,'出征前誓师，在战场中战斗胜利后若获得平蛮勋绩，可以额外获得更多的平蛮勋绩。持续3小时，连续使用时间延长。','使用誓师令可获得3倍的平蛮勋绩，确定要使用么？',1,0,0,'',0,0,0),
     (161004,'驱逐令',1,0,0,0,0,0,10,7,0,'驱逐不齐心协力的队友，使得任务能顺利完成，每天最多使用5次。','战场里面踢人出战场时使用',0,0,0,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (161005,'休整令',1,0,0,0,0,0,5,7,0,'连日征战，军中苦不堪言，欲速则不达。先休整军队，争取时间，一鼓作气歼灭敌军。使用后，增加战场时间1分钟。连续使用，战场时间增长。','使用休整令可增加战场时间1分钟，确定要使用么？',1,0,0,'',0,0,0),
     (161006,'虎咆阵',1,0,0,0,0,0,10,7,0,'古人研究的行军作战阵法，以虎咆哮如雷之气势增加军队士气。使用后，增加战场中军队攻击力30%。持续3小时，连续使用时间延长。','使用虎咆阵可增加军队攻击30%，确定要使用么？',1,0,0,'',0,0,0),
     (161007,'龙鳞阵',1,0,0,0,0,0,10,7,0,'古人研究的行军作战阵法，阵型似龙鳞，易守难攻。使用后，增加战场中军队防御力30%。持续3小时，连续使用时间延长。','使用龙鳞阵可增加军队防御30%，确定要使用么？',1,0,0,'',0,0,0),
     (161008,'幸运符',1,0,0,0,0,0,50,7,0,'使用后，使战场中战斗掉落物品的机率增加5%。持续3小时，连续使用时间延长。','使用幸运符可增加战斗掉落物品机率，确定要使用么？',1,0,0,'',0,0,0),
     (161009,'神行符',1,0,0,0,0,0,30,7,0,'使用后，使战场中的行军速度增加30%。持续3小时，连续使用时间延长。','使用神行符可增加行军速度30%，确定要使用么？',1,0,0,'',0,0,0),
     (161501,'献帝诏书',1,0,0,0,0,0,-1,0,0,'董卓虽立献帝，实则挟天子以令诸侯，献帝困苦，暗发密诏，令天下忠良讨董勤王。使用后，洛阳对该联盟所有成员开放掠夺3天，效果持续3天。唯一存在，可重复获得。','使用后，洛阳对本联盟所有成员开放掠夺，效果持续3天。是否使用？',1,0,0,'',0,0,0),
     (161502,'七星刀柄',1,0,0,0,0,0,-1,0,0,'七星宝刀之刀柄，可与刀刃合成七星宝刀。','可以与七星刀刃合成七星宝刀，是否使用？',1,0,0,'',0,0,0),
     (161503,'七星刀刃',1,0,0,0,0,0,-1,0,0,'七星宝刀之刀刃，可与刀柄合成七星宝刀。','可以与七星刀柄合成七星宝刀，是否使用？',1,0,0,'',0,0,0),
     (161504,'地变符',1,0,0,0,0,0,200,0,0,'匠心独运的变化符，上面绘满古代巧匠根据建筑原理设计出的资源类型转化方式。使用后，可永久转化任意一块资源地为其他类型的同等级的资源地','使用地变符转化资源地请在资源地界面使用',0,0,0,'',0,0,0),
     (164001,'统率至尊鼎',1,0,0,0,0,0,1888,0,164001,'据说鼎内蕴含亿万炼化之法，可炼化天地万物。用于炼化套装，炼化后装备将获得顶级统率附加属性。','至尊统率炼化鼎是在英雄装备界面用于炼化套装的。',1,0,0,'',0,0,0);
REPLACE INTO CFG_GOODS (ID,NAME,INUSE,BATTLE,COPPER_BOX,SILVER_BOX,GOLD_BOX,DIAMOND_BOX,GOODS_VALUE,GROUP_TYPE,IMAGE,DESCRIPTION,USE_GUIDE,AUTO_USE,ZUOQI_TYPE,`LEVEL`,ATTRS,IMAGE_TYPE,BATCH,COMPOSE) VALUES
     (164002,'内政至尊鼎',1,0,0,0,0,0,1888,0,164002,'据说鼎内蕴含亿万炼化之法，可炼化天地万物。用于炼化套装，炼化后装备将获得顶级内政附加属性。','至尊内政炼化鼎是在英雄装备界面用于炼化套装的。',1,0,0,'',0,0,0),
     (164003,'勇武至尊鼎',1,0,0,0,0,0,1888,0,164003,'据说鼎内蕴含亿万炼化之法，可炼化天地万物。用于炼化套装，炼化后装备将获得顶级勇武附加属性。','至尊勇武炼化鼎是在英雄装备界面用于炼化套装的。',1,0,0,'',0,0,0),
     (164004,'智力至尊鼎',1,0,0,0,0,0,1888,0,164004,'据说鼎内蕴含亿万炼化之法，可炼化天地万物。用于炼化套装，炼化后装备将获得顶级智力附加属性。','至尊智力炼化鼎是在英雄装备界面用于炼化套装的。',1,0,0,'',0,0,0),
     (164005,'射程至尊鼎',1,0,0,0,0,0,1888,0,164005,'据说鼎内蕴含亿万炼化之法，可炼化天地万物。用于炼化套装，炼化后装备将获得顶级射程附加属性。','至尊射程炼化鼎是在英雄装备界面用于炼化套装的。',1,0,0,'',0,0,0);
